private OzoneContainer getOzoneContainer(final OzoneConfiguration conf, final DatanodeDetails datanodeDetails) throws IOException {
    testDir = GenericTestUtils.getTestDir(TestCloseContainerCommandHandler.class.getName() + UUID.randomUUID());
    conf.set(HddsConfigKeys.OZONE_METADATA_DIRS, testDir.getPath());
    conf.set(ScmConfigKeys.HDDS_DATANODE_DIR_KEY, testDir.getPath());
    conf.setBoolean(OzoneConfigKeys.DFS_CONTAINER_RATIS_IPC_RANDOM_PORT, true);
    conf.setBoolean(OzoneConfigKeys.DFS_CONTAINER_IPC_RANDOM_PORT, true);
    final DatanodeStateMachine datanodeStateMachine = Mockito.mock(DatanodeStateMachine.class);
    Mockito.when(datanodeStateMachine.getDatanodeDetails()).thenReturn(datanodeDetails);
    Mockito.when(context.getParent()).thenReturn(datanodeStateMachine);
    final OzoneContainer ozoneContainer = new OzoneContainer(datanodeDetails, conf, context, null);
    return ozoneContainer;
}

