@Test
public void testCloseInvalidContainer() throws IOException {
    long containerID = 1234L;
    Configuration conf = new Configuration();
    KeyValueContainerData kvData = new KeyValueContainerData(containerID, (long) StorageUnit.GB.toBytes(1), UUID.randomUUID().toString(), UUID.randomUUID().toString());
    KeyValueContainer container = new KeyValueContainer(kvData, conf);
    kvData.setState(ContainerProtos.ContainerDataProto.State.INVALID);
    // Create Close container request
    ContainerCommandRequestProto closeContainerRequest = ContainerProtos.ContainerCommandRequestProto.newBuilder().setCmdType(ContainerProtos.Type.CloseContainer).setContainerID(DUMMY_CONTAINER_ID).setDatanodeUuid(DATANODE_UUID).setCloseContainer(ContainerProtos.CloseContainerRequestProto.getDefaultInstance()).build();
    dispatcher.dispatch(closeContainerRequest, null);
    Mockito.when(handler.handleCloseContainer(any(), any())).thenCallRealMethod();
    doCallRealMethod().when(handler).closeContainer(any());
    // Closing invalid container should return error response.
    ContainerProtos.ContainerCommandResponseProto response = handler.handleCloseContainer(closeContainerRequest, container);
    Assert.assertTrue("Close container should return Invalid container error", response.getResult().equals(ContainerProtos.Result.INVALID_CONTAINER_STATE));
}

