@Test
public void testUnderReplicatedContainer() throws NodeNotFoundException, ContainerNotFoundException, SCMException {
    final ContainerReportHandler reportHandler = new ContainerReportHandler(nodeManager, containerManager);
    final Iterator<DatanodeDetails> nodeIterator = nodeManager.getNodes(NodeState.HEALTHY).iterator();
    final DatanodeDetails datanodeOne = nodeIterator.next();
    final DatanodeDetails datanodeTwo = nodeIterator.next();
    final DatanodeDetails datanodeThree = nodeIterator.next();
    final ContainerInfo containerOne = getContainer(LifeCycleState.CLOSED);
    final ContainerInfo containerTwo = getContainer(LifeCycleState.CLOSED);
    final Set<ContainerID> containerIDSet = Stream.of(containerOne.containerID(), containerTwo.containerID()).collect(Collectors.toSet());
    nodeManager.setContainers(datanodeOne, containerIDSet);
    nodeManager.setContainers(datanodeTwo, containerIDSet);
    nodeManager.setContainers(datanodeThree, containerIDSet);
    containerStateManager.loadContainer(containerOne);
    containerStateManager.loadContainer(containerTwo);
    getReplicas(containerOne.containerID(), ContainerReplicaProto.State.CLOSED, datanodeOne, datanodeTwo, datanodeThree).forEach(r -> {
        try {
            containerStateManager.updateContainerReplica(containerOne.containerID(), r);
        } catch (ContainerNotFoundException ignored) {
        }
    });
    getReplicas(containerTwo.containerID(), ContainerReplicaProto.State.CLOSED, datanodeOne, datanodeTwo, datanodeThree).forEach(r -> {
        try {
            containerStateManager.updateContainerReplica(containerTwo.containerID(), r);
        } catch (ContainerNotFoundException ignored) {
        }
    });
    // SCM expects both containerOne and containerTwo to be in all the three
    // datanodes datanodeOne, datanodeTwo and datanodeThree
    // Now datanodeOne is sending container report in which containerOne is
    // missing.
    // containerOne becomes under replicated.
    final ContainerReportsProto containerReport = getContainerReportsProto(containerTwo.containerID(), ContainerReplicaProto.State.CLOSED, datanodeOne.getUuidString());
    final ContainerReportFromDatanode containerReportFromDatanode = new ContainerReportFromDatanode(datanodeOne, containerReport);
    reportHandler.onMessage(containerReportFromDatanode, publisher);
    Assert.assertEquals(2, containerManager.getContainerReplicas(containerOne.containerID()).size());
}

