@Test
public void testAllocateBlockRequestWithSuccess() throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String keyName = UUID.randomUUID().toString();
    long allocateBlockClientId = RandomUtils.nextLong();
    String clientId = UUID.randomUUID().toString();
    OMRequest omRequest = createOmRequestForAllocateBlock(volumeName, bucketName, keyName, allocateBlockClientId, clientId);
    OzoneManagerProtocolProtos.OMResponse omResponse = createOmResponseForAllocateBlock(true);
    when(requestHandler.handle(omRequest)).thenReturn(omResponse);
    RaftClientRequest raftClientRequest = new RaftClientRequest(ClientId.randomId(), RaftPeerId.valueOf("random"), raftGroupId, 1, Message.valueOf(OMRatisHelper.convertRequestToByteString(omRequest)), RaftClientRequest.Type.valueOf(RaftProtos.WriteRequestTypeProto.getDefaultInstance()), null);
    TransactionContext transactionContext = ozoneManagerStateMachine.startTransaction(raftClientRequest);
    OMRequest newOmRequest = OMRatisHelper.convertByteStringToOMRequest(transactionContext.getStateMachineLogEntry().getLogData());
    Assert.assertTrue(newOmRequest.hasAllocateBlockRequest());
    checkModifiedOmRequest(omRequest, newOmRequest);
    // Check this keyLocation, and the keyLocation is same as from OmResponse.
    Assert.assertTrue(newOmRequest.getAllocateBlockRequest().hasKeyLocation());
    Assert.assertEquals(omResponse.getAllocateBlockResponse().getKeyLocation(), newOmRequest.getAllocateBlockRequest().getKeyLocation());
}

@Test
public void testAllocateBlockWithFailure() throws Exception {
    String volumeName = UUID.randomUUID().toString();
    String bucketName = UUID.randomUUID().toString();
    String keyName = UUID.randomUUID().toString();
    long allocateBlockClientId = RandomUtils.nextLong();
    String clientId = UUID.randomUUID().toString();
    OMRequest omRequest = createOmRequestForAllocateBlock(volumeName, bucketName, keyName, allocateBlockClientId, clientId);
    OzoneManagerProtocolProtos.OMResponse omResponse = createOmResponseForAllocateBlock(false);
    when(requestHandler.handle(omRequest)).thenReturn(omResponse);
    RaftClientRequest raftClientRequest = new RaftClientRequest(ClientId.randomId(), RaftPeerId.valueOf("random"), raftGroupId, 1, Message.valueOf(OMRatisHelper.convertRequestToByteString(omRequest)), RaftClientRequest.Type.valueOf(RaftProtos.WriteRequestTypeProto.getDefaultInstance()), null);
    TransactionContext transactionContext = ozoneManagerStateMachine.startTransaction(raftClientRequest);
    OMRequest newOmRequest = OMRatisHelper.convertByteStringToOMRequest(transactionContext.getStateMachineLogEntry().getLogData());
    Assert.assertTrue(newOmRequest.hasAllocateBlockRequest());
    checkModifiedOmRequest(omRequest, newOmRequest);
    // As the request failed, check for keyLocation and  the transaction
    // context error message
    Assert.assertFalse(newOmRequest.getAllocateBlockRequest().hasKeyLocation());
    Assert.assertEquals("Scm in Safe mode " + OMException.STATUS_CODE + OMException.ResultCodes.SCM_IN_SAFE_MODE, transactionContext.getException().getMessage());
    Assert.assertTrue(transactionContext.getException() instanceof IOException);
}

